ASSERT_MSG = '\n'.join(["{message}", "Expected: {expected}", "But was: {current}"])


def wait_until_check_succeeds(retry, retry_interval):
    """     Decorator to repeatedly execute a function until it succeeds or a timeout is reached.
            if argument increase_time_for_check != False in calling decorated function 'll overwrite param retry,
    :param int retry: The maximum time (in seconds) to keep retrying the decorated function.
    :param int retry_interval: The interval (in seconds) between retries.
    :return: The result of the decorated function if it succeeds within the retry period.
    :raises BTSElementCheckingTimeout: If the function does not succeed within the retry period.
    """
    def decorator(func):
        @wraps(func)
        def wrapper(*argv, **kwargs):
            if 'increase_time_for_check' not in kwargs:
                retry_time = retry
            elif kwargs['increase_time_for_check'] is False:
                del kwargs['increase_time_for_check']
                retry_time = retry
            else:
                retry_time = kwargs.pop('increase_time_for_check')
            max_time = time.time() + int(retry_time)
            while True:
                iteration_start_time = time.time()
                try:
                    return func(*argv, **kwargs)
                except Exception as err:
                    log_info_to_console(f'Check {func.__name__} failed. It will be continued for another '
                                        f'{(max_time - time.time())} seconds.', log_hierarchy=3)
                    if str(err) != "name 'assert_msg' is not defined":
                        log_info_to_console(f'Last error: {err}', log_hierarchy=3)
                    if time.time() > max_time:
                        log_warn_to_console(f'Checking {func.__name__} failed after retrying {retry_time}s.')
                        raise BTSElementCheckingTimeout(err)
                    sleeping_time = retry_interval - (time.time() - iteration_start_time)
                    time.sleep(sleeping_time) if sleeping_time > 0 else None
        return wrapper
    return decorator


class GenericBtsPreparator(GenericBts):
    def __init__(self, bts_type, bts_comm, bts_du, bts_alarm, bts_log, bts_ru, bts_cell, asir_commissioning,
                 bts_id=0, du_id=0, log_dir=None):
        self.bts_type = bts_type
        self.bts_comm = bts_comm
        self.bts_du = bts_du
        self.bts_ru = bts_ru
        self.bts_cell = bts_cell
        self.bts_alarm = bts_alarm
        self.bts_log = bts_log
        self.asir_commissioning = asir_commissioning
        self.du_id = du_id
        self.bts_id = bts_id
        self.bts_connection_name = self.bts_comm.rest_alias.format(bts_id, du_id)
        self.log_dir = log_dir if log_dir is not None else get_builtin_value('OUTPUT DIR')
        os.makedirs(self.log_dir, exist_ok=True)

        super(GenericBtsPreparator, self).__init__(bts_type=bts_type)

    @log_as_robot_keyword
    @wait_until_check_succeeds(retry=90, retry_interval=30)
    def connect(self, interface='mplane', force=False, reconnect_attempts=3, timeout=60):
        base_dir = os.path.abspath(os.path.join(self.log_dir, '..'))
        admin_log_dir = self.bts_log._get_admin_api_log_dir(bts_id=self.bts_id, du_id=self.du_id, base_dir=base_dir)
        super(GenericBtsPreparator, self).connect(bts_id=self.bts_id, du_id=self.du_id,
                                                  interface=interface, force=force,
                                                  reconnect_attempts=reconnect_attempts, timeout=timeout,
                                                  log_dir=admin_log_dir)

    @log_as_robot_keyword
    def prepare_main_bts(self,
                         scf_path,
                         sw_conf_path,
                         main_bts,
                         enbs,
                         incompatible_error_timer,
                         increase_timeout_for_update_sw,
                         increase_time_for_checking_bbmod,
                         increase_time_for_checking_radios,
                         increase_time_for_checking_cells,
                         increase_time_for_checking_X2link,
                         scf_prefix_tag=None,
                         wait_for_on_air=True,
                         wtd_sfp_wa_support=False,
                         bsr_config_file=None,
                         certificates=None,
                         rusw=None,
                         check_x2_link=True):
        """    Function to prepare main BTS to On-Air state.
        :param str scf_path: Path to SCF file,
        :param str sw_conf_path: Path to sw_config.txt file,
        :param dict main_bts: btc config based on __init__.py
        :param list[str] enbs: List of existing ENB neighbour (to check X2 Link),
        :param int incompatible_error_timer: Increase time to wait for "Incopatible SW detected",
        :param int increase_timeout_for_update_sw: Increase time to wait for update SW on BTS,
        :param int increase_time_for_checking_bbmod: Increase timeout for checking BBMOD,
        :param int increase_time_for_checking_radios:  Increase timeout for checking Radios,
        :param int increase_time_for_checking_cells: Increase timeout for checking Cells,
        :param int increase_time_for_checking_X2link: Increase timeout for checking X2 Link,
        :param str scf_prefix_tag: scf prefix tag - to indicate specific SCF eg: scf_prefix_tag=4CC --> 4CC_GNB0_SCF.xml
        :param bool wait_for_on_air: wait till BTS is in On-Air state. If False - waiting till SMOD/BBMOD/RMOD are up.
        :param bool wtd_sfp_wa_support: Specifies whether WTD SFP workaround should be enabled
        :param str bsr_config_file: Path to BSR configuration file,
        :param list certificates: List of dictionaries with certificate parameters to be installed on the BTS,
        :param str rusw: Independent RU SW package name,
        :param bool check_x2_link: Specifies whether X2 Link check should be performed,
        :return: None.
        """
        self.connect(increase_time_for_check=False, interface='lmp')
        node_name = next(iter(main_bts))
        if sw_conf_path:
            self.upload_sw_conf(node_name=node_name,
                                sw_conf_path=sw_conf_path,
                                bts_conf=list(main_bts.values())[0])

        if certificates:
            self.download_and_install_certificates(certificates)

        if bsr_config_file:
            self.download_and_load_bsr_config(bsr_config_file)

        if rusw:
            self.download_and_load_rusw(rusw)
            time.sleep(30)

        bts_scf_path, bts_scf_file = self.commission_scf(node_name=node_name,
                                                         scf_path=scf_path,
                                                         scf_prefix_tag=scf_prefix_tag)

        self.connect(force=True, interface='mplane')

        self.wait_for_incompatible_software(
            incompatible_error_timer=incompatible_error_timer,
            increase_timeout_for_update_sw=increase_timeout_for_update_sw,
            increase_time_for_checking_bbmod=increase_time_for_checking_bbmod,
            rusw=rusw,
        )
        self.commission_scf_on_asir_if_needed(scf_file=bts_scf_file, node_name=node_name,
                                              scf_path=bts_scf_path, scf_prefix_tag=scf_prefix_tag)
        self.wait_for_bts_on_air_state(increase_time_for_checking_radios=increase_time_for_checking_radios,
                                       increase_time_for_checking_cells=increase_time_for_checking_cells,
                                       wait_for_on_air=wait_for_on_air,
                                       wtd_sfp_wa_support=wtd_sfp_wa_support)

        if check_x2_link:
            if enbs and self.bts_type == 'GNB':
                log_info_to_console('Check X2 Link', log_hierarchy=2)
                self.check_x2_link(increase_time_for_check=increase_time_for_checking_X2link)
                log_info_to_console('X2 Link checked - everything works', log_hierarchy=3)

        log_banner_to_console('Main BTS Station prepared')

    @log_as_robot_keyword
    def download_and_load_bsr_config(self, bsr_config_file):
        """    Downloads the specified BSR (Beam Set Reference) configuration file and loads it onto the BTS.
        :param str bsr_config_file: The name of the BSR configuration file to be downloaded and loaded.
        :raises FileNotFoundError: If the BSR configuration file does not exist after download.
        :return: None
        """
        log_info_to_console('BSR configuration will be uploaded to BTS', log_hierarchy=2)
        bsr_config_file_path = self.download_bsr_sw_package(bsr_sw=bsr_config_file)
        self.load_bsr_config(bsr_config_file=bsr_config_file_path)

    @log_as_robot_keyword
    def download_and_install_certificates(self, certificates):
        """    Downloads and installs certificates on the BTS.
        :param list[dict] certificates: A list of dictionaries containing certificate parameters.
                                        Each dictionary should include:
                                        - 'cert_file' (str): Name of the certificate file to be downloaded.
                                        - 'cert_type' (str): Type of the certificate (e.g., 'CA', 'Server').
                                        - 'password' (str): Password for the certificate, if required.
                                        - 'key_pool_type' (str): Key pool type for the certificate.
        :return: None
        """
        log_info_to_console('Certificates will be uploaded to BTS', log_hierarchy=2)
        self.download_certs(certs=certificates)
        self.install_certificates(certificates=certificates)

    @log_as_robot_keyword
    def download_and_load_rusw(self, rusw, timeout=600):
        """    Downloads the specified RUSW (Independent RU Software Package) and loads it onto the BTS.
        This method downloads the RUSW package from the specified source, uploads it to the BTS,
        and ensures that the software is properly updated within the given timeout.
        :param str rusw: The name of the RUSW package to be downloaded and loaded.
        :param int timeout: The maximum time (in seconds) to wait for the RUSW upload process. Defaults to 100 seconds.
        :raises FileNotFoundError: If the RUSW package file does not exist after download.
        :raises AdminApiProcedureFailureException: If the RUSW upload process
        :return: None
        """
        log_info_to_console('Independent RU SW package will be downloaded and uploaded to BTS', log_hierarchy=2)
        rusw_file_path = self.download_rusw_package(rusw=rusw)
        log_info_to_console('Uploading Independent RU software to BTS', log_hierarchy=3)
        log_info_to_console('Proper settings for Independent RUSW should be included in SCF.', log_hierarchy=3)
        self.try_to_update_bts_software(timeout, rusw_file_path)

    @log_as_robot_keyword
    def prepare_bts_neighbour(self,
                              neighbour_name,
                              neighbour_info,
                              scf_path,
                              sw_conf_path,
                              upload_sw_config,
                              neighbour_incompatible_error_timer,
                              neighbour_increase_timeout_for_update_sw,
                              increase_time_for_checking_neighbour_bbmod,
                              increase_time_for_checking_neighbour_radios,
                              increase_time_for_checking_neighbour_cells,
                              scf_prefix_tag=None,
                              certificates=None):
        """    Function to prepare main BTS to On-Air state.
        :param str neighbour_name: BTS neighbour name,
        :param str neighbour_info: BTS additional neighbour info,
        :param str scf_path: Path to SCF file,
        :param str sw_conf_path: Path to sw_config.txt file,
        :param bool upload_sw_config: Upload swconfig.txt fole to the neighbour if param is True,
        :param int neighbour_incompatible_error_timer: Increase time to wait for "Incopatible SW detected" on neighbour,
        :param int neighbour_increase_timeout_for_update_sw: Increase time to wait for update SW on BTS,
        :param int increase_time_for_checking_neighbour_bbmod: Increase timeout for checking neighbour BBMOD,
        :param int increase_time_for_checking_neighbour_radios:  Increase timeout for checking neighbour Radios,
        :param int increase_time_for_checking_neighbour_cells: Increase timeout for checking neighbour Cells,
        :param str scf_prefix_tag: scf prefix tag - to indicate specific SCF eg: scf_prefix_tag=4CC --> 4CC_GNB0_SCF.xml
        :param list certificates: List of dictionaries with certificate parameters to be installed on the BTS,
        :return: None.
        """
        self.connect(increase_time_for_check=False, interface='lmp')
        if sw_conf_path and upload_sw_config:
            self.upload_sw_conf(node_name=neighbour_name, sw_conf_path=sw_conf_path, bts_conf=neighbour_info)
        if certificates:
            self.download_and_install_certificates(certificates)

        actual_build = self.bts_comm.admin.get_sw_version(connection=self.bts_connection_name)
        selected_build = get_selected_build(actual_build)
        if self._check_if_fsmr3():
            fsm_build = self._get_proper_build_name_for_fsm(build=selected_build)
            if fsm_build:
                selected_build = fsm_build
        ab = SwVersionFactory.create_sw_version(actual_build)
        sb = SwVersionFactory.create_sw_version(selected_build)
        if ab != sb:
            log_info_to_console('Different build on neighbour detected', log_hierarchy=2)
            log_info_to_console(f'Build on neighbour will be changed to {selected_build}', log_hierarchy=2)
            try:
                path_to_sw = self.download_bts_sw_package(sw=selected_build)
            except SwUpgradeException:
                log_warn_to_console('SW download failed - check why', log_hierarchy=3)
            log_info_to_console('Configuration Reset on neighbour', log_hierarchy=2)
            self.bts_comm.reset_configuration(bts_id=self.bts_id, du_id=self.du_id)
            self.update_software(sw_package=path_to_sw,
                                 connection=self.bts_connection_name,
                                 timeout=neighbour_increase_timeout_for_update_sw)
            self.disconnect(bts_id=self.bts_id, du_id=self.du_id)
            # sleep for BTS availability after software update
            time.sleep(120)
            self.connect(increase_time_for_check=False, interface='lmp')
        else:
            log_info_to_console('Selected build already installed on neighbour - perform commissioning',
                                log_hierarchy=1)

        bts_scf_path, bts_scf_file = self.commission_scf(node_name=neighbour_name,
                                                         scf_path=scf_path, scf_prefix_tag=scf_prefix_tag)

        self.connect(force=True, interface='mplane')

        self.wait_for_incompatible_software(
            incompatible_error_timer=neighbour_incompatible_error_timer,
            increase_timeout_for_update_sw=neighbour_increase_timeout_for_update_sw,
            increase_time_for_checking_bbmod=increase_time_for_checking_neighbour_bbmod,
        )
        self.commission_scf_on_asir_if_needed(scf_file=bts_scf_file, node_name=neighbour_name,
                                              scf_path=bts_scf_path, scf_prefix_tag=scf_prefix_tag)
        self.wait_for_bts_on_air_state(increase_time_for_checking_radios=increase_time_for_checking_neighbour_radios,
                                       increase_time_for_checking_cells=increase_time_for_checking_neighbour_cells)

        log_banner_to_console(f'{neighbour_info["bts_type"]} Neighbour {neighbour_name} prepared.')

    def _check_if_fsmr3(self):
        """ Checks if the BTS (Base Transceiver Station) is of type FSMr3.
        :return bool: True if the BTS product code is "FSMr3", otherwise False.
        """
        bts_info = self.bts_du.get_bts_info(bts_id=self.bts_id, du_id=self.du_id)
        if bts_info['cabinets'][0]['productCode'] == "FSMr3":
            return True
        return False

    def _get_proper_build_name_for_fsm(self, build):
        """     Determines the proper build name for FSM based on the provided build string.
        :param str build: The current build string, e.g., 'SBTS23R1_FSM3_0000_000084_000000'.
        :return str or None: The proper build name for FSM if applicable, otherwise None.
        """
        branch_name_no = int(re.search(r'SBTS(?P<RELEASE_NUMBER>\d+)(R\d+)?_', build).group('RELEASE_NUMBER'))
        if self.bts_type == 'ENB':
            if branch_name_no >= 23:
                return WftApi(project='SBTS', component=f'{build.split("_")[0]}_FSM3',
                              version='').get_newest_released_branch_name()
            elif branch_name_no == 0:
                return WftApi(project='SBTS', component='SBTS00_FSM3', version='').get_newest_released_branch_name()

    @log_as_robot_keyword
    def wait_for_incompatible_software(self,
                                       incompatible_error_timer,
                                       increase_timeout_for_update_sw,
                                       increase_time_for_checking_bbmod,
                                       rusw=None):
        """    Waits for the "Incompatible Software Detected" alarm and handles the software update process if needed.
        This method checks if the "Incompatible Software Detected" alarm appears within the specified time.
        If the alarm is raised, it downloads the appropriate software and updates the BTS. Additionally,
        it verifies the Base Band Module (BBMOD) status and ensures the software update process is completed.
        :param int incompatible_error_timer: Time in seconds to wait for the "Incompatible Software Detected" alarm.
        :param int increase_timeout_for_update_sw: Time in seconds to wait for the software update process to complete.
        :param int increase_time_for_checking_bbmod: Time in seconds to wait for the BBMOD status check.
        :param str or None rusw: Name of the Independent RU Software Package, if applicable. Defaults to None.
        :raises SWDowloadError: If the software download fails.
        :raises AdminApiProcedureFailureException: If the software update process encounters an error.
        :return: None
        """
        log_info_to_console('Check BTS is On-Air state')
        log_info_to_console('Check Base Band Module', log_hierarchy=2)
        self.check_bbmod(increase_time_for_check=increase_time_for_checking_bbmod)
        log_info_to_console('Base Band Module checked - everything works', log_hierarchy=3)
        self.check_is_sw_incompatible(awaiting_time=incompatible_error_timer,
                                      increase_timeout_for_update_sw=int(increase_timeout_for_update_sw),
                                      rusw=rusw)

    @log_as_robot_keyword
    def wait_for_bts_on_air_state(self,
                                  increase_time_for_checking_radios,
                                  increase_time_for_checking_cells,
                                  wait_for_on_air=True,
                                  wtd_sfp_wa_support=False):
        """    Function is checking every single component of BTS On-Air state,,
        :param int increase_time_for_checking_radios:  Increase timeout for checking Radios,
        :param int increase_time_for_checking_cells: Increase timeout for checking Cells,
        :param bool wait_for_on_air: Wait for BTS is in On-Air state. If False - wait for SDMOD/BBMOD/RUMOD are up.
        :param bool wtd_sfp_wa_support: Specifies whether WTD SFP workaround should be enabled
        :return: None.
        """
        log_info_to_console('Check Radios', log_hierarchy=2)
        self.check_radios(increase_time_for_check=increase_time_for_checking_radios, interface='mplane', force=True)
        log_info_to_console('Radios checked - everything works', log_hierarchy=3)
        if wtd_sfp_wa_support:
            self.bts_ru.remove_disablerxloswa_flag_from_all_rus()
        if wait_for_on_air:
            log_info_to_console('Check cells', log_hierarchy=2)
            self.check_cells(increase_time_for_check=increase_time_for_checking_cells)
            log_info_to_console('Cells checked - everything works', log_hierarchy=3)
        else:
            log_info_to_console("Skip checking Cells state", log_hierarchy=2)

    @log_as_robot_keyword
    def upload_sw_conf(self, node_name, sw_conf_path, bts_conf):
        """    Function is uploading sw_config.txt file to BTS,
        :param str node_name: Phrase to upload swconfig.txt file in proper node,
        :param str sw_conf_path: Path to sw_config.txt file,
        :param dict bts_conf: BTS config based on __init__.py - to get info about FullRack
        :return: None.
        """
        log_info_to_console(f'Upload swconfig.txt to {node_name}')
        sw_conf_path = sw_conf_path if os.path.exists(sw_conf_path) \
            else os.path.join(get_repository_path(), sw_conf_path)
        self.bts_du.upload_swconfig(sw_config_path=sw_conf_path, bts_id=self.bts_id, du_id=self.du_id)
        if bts_conf['is_fullrack']:
            log_info_to_console('BTS is probably FullRack. Upload sw_config.txt to second half of FullRack BTS')
            self.bts_du.upload_swconfig(sw_config_path=sw_conf_path, bts_id=self.bts_id, du_id=self.du_id, cu_id=1)

        shutil.copy(sw_conf_path, os.path.join(self.log_dir, f'sw_config_uploaded_to_{node_name}.txt'))
        log_info_to_console(f'swconfig.txt collected in location: {self.log_dir}')

    @log_as_robot_keyword
    def commission_scf(self, node_name, scf_path, scf_prefix_tag=None):
        """    Function is validating SCF file and upload it to BTS,
        :param str node_name: Phrase to find proper SCF file in SCF locations,
        :param str scf_path: Path to SCF file,
        :param str scf_prefix_tag: scf prefix tag - to indicate specific SCF eg: scf_prefix_tag=4CC --> 4CC_GNB0_SCF.xml
        :return: None.
        """
        self.connect(increase_time_for_check=False, interface='lmp')
        sw = self.bts_comm.admin.get_sw_version(connection=self.bts_connection_name)
        log_info_to_console('Validate SCF and load to BTS')
        try:
            scf_path = scf_path if scf_path else get_scf_path(sw_name=sw)
            scf_file = get_node_scf_path(node_name=node_name, branch_scf_path=scf_path,
                                         bts_type=self.bts_type, bts_id=self.bts_id, scf_prefix_tag=scf_prefix_tag)
            log_info_to_console(f'SCF {scf_file} will be verified and uploaded to BTS', log_hierarchy=2)
            self.bts_comm.admin.validate_scf_online(scf_file=scf_file,
                                                    skip_parameter_relation_errors=False,
                                                    detailed_output=True,
                                                    connection=self.bts_connection_name)
        except Exception as err:
            log_warn_to_console('SCF validation failed\n{}')
            raise AdminApiProcedureFailureException(err)

        self.bts_comm.perform_bts_full_commissioning(scf_file=scf_file,
                                                     bts_id=self.bts_id,
                                                     skip_parameter_relation_errors=True,
                                                     should_activate=True,
                                                     validate_scf=False,
                                                     timeout=600,
                                                     du_id=self.du_id)
        log_info_to_console('Uploaded SCF file', log_hierarchy=2)
        return scf_path, scf_file

    @log_as_robot_keyword
    def commission_scf_on_asir_if_needed(self, scf_file, node_name, scf_path, scf_prefix_tag=None):
        """    Function is validating SCF file and upload it to ASIR,
        :param str scf_file: SCF file name in SCF locations,
        :param str node_name: Phrase to find proper SCF file in SCF locations,
        :param str scf_path: Path to SCF file,
        :param str scf_prefix_tag: scf prefix tag - to indicate specific SCF eg: scf_prefix_tag=4CC --> 4CC_GNB0_SCF.xml
        :return: None.
        """
        if is_asir_configuration(scf_path=scf_file):
            log_info_to_console('Wait when all ASIRs are up', log_hierarchy=2)
            self.connect(increase_time_for_check=False, interface='mplane', force=True)
            self.bts_ru.wait_for_all_radio_units_to_be_online(bts_id=self.bts_id, du_id=self.du_id,
                                                              skip_ru_if_not_configured=True, timeout=900)
            asir_scf_file = get_node_scf_path(node_name=node_name, branch_scf_path=scf_path,
                                              bts_type=self.bts_type, bts_id=self.bts_id, sub_device='ASIR',
                                              scf_prefix_tag=scf_prefix_tag)
            log_info_to_console(f'ASIR SCF {asir_scf_file} will be uploaded to BTS', log_hierarchy=2)
            try:
                self.commission_scf_on_asir(scf_path=asir_scf_file)
            except Exception as err:
                msg = f"Upload ASIR SCF  {asir_scf_file} FAILED\n{err}"
                logging.error(msg)
                raise err
            log_info_to_console('Uploaded ASIR SCF file', log_hierarchy=2)

    @log_as_robot_keyword
    def commission_scf_on_asir(self, scf_path):
        """    Function is getting proper ASIR SCF and uploading it to BTS,
        :param str scf_path: Path to SCF file,
        :return: None.
        """
        self.asir_commissioning(bts_id=self.bts_id, scf_path=scf_path)
        logging.debug("Waiting 60 sec for HUB Reset and UP")
        time.sleep(60)

    @log_as_robot_keyword
    def download_bsr_sw_package(self, bsr_sw, builds_dir=None):
        """     Downloads the specified BSR (Beam Set Reference) software package.
        :param str bsr_sw: Name of the BSR software package to download. Must be provided as a string.
        :param builds_dir: Directory where the BSR software package will be downloaded. Defaults to
                           '/home/ute/.ute-ca/cache/bts' if not specified.
        :return str: Path to the downloaded BSR software package.
        :raise: ValueError: If `bsr_sw` is not provided as a string.
        """
        sw_name_raw = re.match(r'^(.*)\.zip$', bsr_sw).group(1)
        artifactory_bsr_url = \
            'https://artifactory-espoo1.ext.net.nokia.com:443/artifactory/mnpute-rotta-local/BSR/'
        url = f'{artifactory_bsr_url.rstrip("/")}/{bsr_sw}'
        api_key = SwVersion(raw='temp', url=artifactory_bsr_url).api_key
        return self._download_sw_package(sw_name_raw, bsr_sw, url, api_key, builds_dir)

    @log_as_robot_keyword
    def download_bts_sw_package(self, sw=False, builds_dir=None):
        """     Downloads the specified BTS software package.
        :param str sw: Name of the software package to download. If not provided, the current software version
                       will be retrieved from the BTS.
        :param builds_dir: Directory where the BSR software package will be downloaded. Defaults to
                           '/home/ute/.ute-ca/cache/bts' if not specified.
        :return str: Path to the downloaded BSR software package.
        """
        if not sw:
            self.connect(increase_time_for_check=False, interface='lmp')
            sw = self.bts_comm.admin.get_sw_version(connection=self.bts_connection_name)
        sw_name = SwVersionFactory.create_sw_version(sw)
        sw_name_raw = sw_name.raw
        sw_package_name = sw_name.get_package()
        url = sw_name.url
        api_key = sw_name.api_key
        return self._download_sw_package(sw_name_raw, sw_package_name, url, api_key, builds_dir)

    @log_as_robot_keyword
    def download_certs(self, certs, builds_dir=None):
        """    Downloads certificates from the specified URL and saves them to the target directory.
        :param list[dict] certs: A list of dictionaries containing certificate parameters.
                                 Each dictionary should include:
            - 'cert_file' (str): Name of the certificate file to be downloaded.
        :param str/None builds_dir: Directory where the certificates will be saved. Defaults to
                                    '/home/ute/.ute-ca/cache/bts' if not specified.
        :return: None
        """
        location, tl_name = get_configuration()
        artifactory_cert_url = \
            f'https://artifactory-espoo1.ext.net.nokia.com:443/artifactory/mnpute-rotta-local/certs'
        url = f'{artifactory_cert_url}/{location}/{tl_name}'
        api_key = SwVersion(raw='temp', url=artifactory_cert_url).api_key
        for cert in certs:
            cert_file = cert['cert_file']
            cert['cert_file'] = self._download_sw_package('certs', cert_file, f'{url}/{cert_file}',
                                                          api_key, builds_dir)

    @log_as_robot_keyword
    def download_rusw_package(self, rusw, builds_dir=None):
        """    Downloads the specified RUSW (Independent RU Software Package) from the repository.
        This method retrieves the RUSW package based on the provided name, downloads it from the repository,
        and saves it to the specified directory. If no directory is provided, the default directory is used.
        :param str rusw: The name of the RUSW package to be downloaded.
        :param str or None builds_dir: The directory where the RUSW package will be saved. Defaults to
                                       '/home/ute/.ute-ca/cache/bts' if not specified.
        :raises ValueError: If the `rusw` parameter is not provided or invalid.
        :raises Exception: If the download process encounters an error.
        :return str: The path to the downloaded RUSW package.
        """
        sw_name = SwVersionFactory.create_sw_version(rusw)
        sw_name_raw = sw_name.raw
        url = sw_name.url
        cmp_and_ver = sw_name.component_name_and_version
        api_key = sw_name.api_key
        return self._download_sw_package(cmp_and_ver, sw_name_raw, url, api_key, builds_dir)

    def _download_sw_package(self, sw_name_raw, sw_package_name, url, api_key, builds_dir=None):
        """     Downloads a software package from the specified URL and saves it to the target directory.
        :param str sw_name_raw: Raw name of the software package (used for creating the target directory).
        :param str sw_package_name: Name of the software package file to be downloaded.
        :param str url: URL from which the software package will be downloaded.
        :param str builds_dir: Directory where the software package will be saved. Defaults to
                               '/home/ute/.ute-ca/cache/bts' if not specified.
        :param str api_key: API key for authentication during the download.
        :return str: Path to the downloaded software package.
        """
        target_dir = '/home/ute/.ute-ca/cache/bts' if not builds_dir else builds_dir
        sw_package_path = os.path.join(target_dir, sw_name_raw)
        downloaded_sw_path = self._get_sw_path_if_already_downloaded(target_dir=target_dir, sw_name=sw_package_name)

        if downloaded_sw_path:
            log_info_to_console(f'SW {sw_package_name} already in directory {downloaded_sw_path}', log_hierarchy=3)
            return downloaded_sw_path
        else:
            log_info_to_console(f'Downloading SW {sw_package_name} from {url}', log_hierarchy=3)
            if not os.path.exists(sw_package_path): Path(sw_package_path).mkdir(parents=True)
            path_to_sw = os.path.join(sw_package_path, sw_package_name)
            GenericSwUpdate(bts_type=self.bts_type, comm=self.bts_comm).download_from_arti(
                url=url, local_sw_file_path=path_to_sw, api_key=api_key)
            return path_to_sw

    @staticmethod
    def _get_sw_path_if_already_downloaded(target_dir, sw_name):
        """     Checks if the specified software package is already downloaded in the target directory.
        :param str target_dir: The directory to search for the software package.
        :param str sw_name: The name of the software package to search for.
        :return str or bool: The full path to the software package if found, otherwise False.
        """
        sw_regex = re.compile(sw_name)
        for root, dirs, files in os.walk(target_dir):
            for file_name in files:
                if file_name and sw_regex.match(file_name):
                    return os.path.join(root, file_name)
        return False

    @log_as_robot_keyword
    @wait_until_check_succeeds(retry=300, retry_interval=30)
    def check_bbmod(self):
        """    Function if to check that Base Band Modules are in proper state, Timeouted with decorator.
        :return: None.
        """
        self.connect(increase_time_for_check=False, interface='lmp')
        self.bts_du.verify_bbmod_statuses(operational_state='enabled',
                                          procedural_status='configured',
                                          availability_status='online',
                                          administrative_state='unlocked',
                                          bts_id=self.bts_id, du_id=self.du_id)

    @log_as_robot_keyword
    def check_is_sw_incompatible(self, awaiting_time, increase_timeout_for_update_sw=600, rusw=None):
        """    Function is to check that incompatible software is on BTS.
               If Incompatible software detected on BTS proper software is downloaded.
        :return: None.
        """
        incompatible_sw, incompatible_sw_on_all_rus, incompatible_sw_on_rusw = \
            self.check_if_sw_incompatible_alarm_occurred(awaiting_time)
        if incompatible_sw_on_all_rus or incompatible_sw:
            log_info_to_console('Incompatible Sw detected', log_hierarchy=3)
            try:
                path_to_sw = self.download_bts_sw_package()
            except Exception as err:
                log_warn_to_console('SW download failed - check why', log_hierarchy=3)
                raise SWDowloadError(err)

            self.check_if_gps_firmware_is_ongoing()
            self.try_to_update_bts_software(increase_timeout_for_update_sw, path_to_sw)

        if rusw and incompatible_sw_on_rusw:
            log_info_to_console('Incompatible Sw on Independent RU detected', log_hierarchy=3)
            try:
                path_to_rusw = self.download_rusw_package(rusw)
            except Exception as err:
                log_warn_to_console('RUSW download failed - check why', log_hierarchy=3)
                raise SWDowloadError(err)
            self.check_if_gps_firmware_is_ongoing()
            self.try_to_update_bts_software(increase_timeout_for_update_sw, path_to_rusw)

    @log_as_robot_keyword
    def try_to_update_bts_software(self, increase_timeout_for_update_sw, path_to_sw):
        attempt = 1
        max_attempts = 3
        sw_upload_error = None
        while attempt <= max_attempts:
            try:
                self.update_software(sw_package=path_to_sw,
                                     connection=self.bts_connection_name,
                                     timeout=int(increase_timeout_for_update_sw))
                break
            except AdminApiProcedureFailureException as sw_upload_error:
                if 'BTS is busy' in repr(sw_upload_error):
                    log_warn_to_console(f"Attempt number {attempt} failed because 'BTS is busy'", log_hierarchy=4)
                    logging.debug(repr(sw_upload_error))
                    log_warn_to_console('Wait 60 sec and try again', log_hierarchy=4)
                    attempt += 1
                    time.sleep(60)
                    continue
                raise sw_upload_error
        else:
            raise sw_upload_error
        log_info_to_console('Software uploaded successfully', log_hierarchy=3)

    @log_as_robot_keyword
    def check_if_gps_firmware_is_ongoing(self):
        try:
            self.bts_alarm.verify_alarm_is_active(fault_name='GPS receiver alarm: firmware upgrade ongoing')
            log_info_to_console('GPS firmware upgrade ongoing - wait for finish', log_hierarchy=3)
            self.bts_alarm.wait_for_alarm_deactivation(fault_id=4420, awaiting_time=1800)
            log_info_to_console('GPS firmware upgrade finish', log_hierarchy=3)
            # sleep for BTS availability after GPS firmware upgrade
            time.sleep(60)
        except AlarmIsNotActive:
            log_info_to_console('GPS firmware upgrade alarm is not active, continue', log_hierarchy=3)

    @log_as_robot_keyword
    def check_if_sw_incompatible_alarm_occurred(self, awaiting_time, rusw=None):
        """    Checks if the "Incompatible Software Detected" alarm has occurred on the BTS.
        This method waits for the "Incompatible Software Detected" alarm to appear within the specified time.
        It verifies if the alarm is raised for all RUs (Radio Units) or specific RUs. If the `rusw` parameter
        is provided, it checks for incompatibility specific to the Independent RU Software Package.
        :param int awaiting_time: Time in seconds to wait for the "Incompatible Software Detected" alarm.
                                  Defaults to 600 seconds if not provided.
        :param str or None rusw: Name of the Independent RU Software Package, if applicable. Defaults to None.
        :return tuple[bool, bool, bool]: A tuple containing three boolean values:
                                         - `incompatible_sw`: True if the alarm is detected for the BTS.
                                         - `incompatible_sw_on_all_rus`: True if the alarm is detected for all RUs.
                                         - `incompatible_sw_on_rusw`: True if the alarm is detected for
                                            the specified RUSW.
        """
        awaiting_time = 600 if not awaiting_time else int(awaiting_time)
        log_info_to_console(f'Waiting for Incompatible Sw detected for {awaiting_time}s', log_hierarchy=3)
        incompatible_sw = False
        incompatible_sw_on_rusw = False
        incompatible_sw_on_all_rus = self.bts_alarm.check_if_sw_incompatible_alarm_occurred(
            awaiting_time=awaiting_time,
            bts_id=self.bts_id,
            du_id=self.du_id,
            check_on_all_rus=True)
        if not incompatible_sw_on_all_rus:
            incompatible_sw = self.bts_alarm.check_if_sw_incompatible_alarm_occurred(
                awaiting_time=awaiting_time,
                bts_id=self.bts_id,
                du_id=self.du_id,
                check_on_all_rus=False)
        if rusw:
            active_alarms = self.bts_comm.admin.get_active_alarms(connection=self.bts_connection_name)
            for alarm in active_alarms:
                if re.search('Incompatible SW version detected', alarm['faultName']):
                    radio_name_rusw = re.search(r'(?<=\bRUSW_)[^_]+', rusw).group(0)
                    if re.search(radio_name_rusw, str(alarm['alarmAttribute'])):
                        incompatible_sw_on_rusw = True
        return incompatible_sw, incompatible_sw_on_all_rus, incompatible_sw_on_rusw

    @log_as_robot_keyword
    def update_software(self, sw_package, connection, timeout):
        """     Updates the software on the BTS by uploading the specified software package.
        :param str sw_package: The path to the software package to be uploaded.
        :param str connection: The connection name used to communicate with the BTS.
        :param int timeout: The maximum time (in seconds) to wait for the software update process to complete.
        :return: None
        """
        self._wait_for_bts_ready(connection=connection)
        log_info_to_console('Uploading software to BTS', log_hierarchy=3)
        self.bts_comm.admin.update_software(sw_package=sw_package,
                                            connection=connection,
                                            timeout=timeout)

    def _wait_for_bts_ready(self, connection, timeout=600):
        """     Waits for the BTS to be ready for a software update.
        :param str connection: The connection name used to communicate with the BTS.
        :param int timeout: The maximum time (in seconds) to wait for the BTS to be ready.
        :return: None
        """
        self.connect(increase_time_for_check=False, interface='lmp')
        log_info_to_console(f'Waiting max {timeout} seconds for BTS is ready before Software Update',
                            log_hierarchy=3)
        self.bts_comm.admin.wait_sw_update_possible(readiness_timeout=timeout,
                                                    timeout=(timeout + 100),
                                                    connection=connection)

    @log_as_robot_keyword
    @wait_until_check_succeeds(retry=900, retry_interval=30)
    def check_radios(self, interface='lmp', force=False):
        """    Function is to check that all Radios are in proper state.
               If Incompatible software detected on BTS proper software is downloaded.
               Timeouted with decorator.
        :param str interface: The interface to use for the connection (default is 'lmp').
        :param bool force: Whether to force the connection (default is False).
        :return: None
        :raises BTSElementCheckingTimeout: If the radios are not in the expected state within the timeout period.
        """
        self.connect(increase_time_for_check=False, interface=interface, force=force)
        self.bts_ru.verify_all_radio_units_are_online(bts_id=self.bts_id, du_id=self.du_id,
                                                      skip_ru_if_not_configured=True)

    @log_as_robot_keyword
    @wait_until_check_succeeds(retry=360, retry_interval=30)
    def check_cells(self):
        """    Function if to check that all cells are in proper state
               Timeouted with decorator.
        :return: None.
        :raises BTSElementCheckingTimeout: If the cells are not in the expected state within the timeout period.
        """
        self.connect(increase_time_for_check=False, interface='mplane')
        self.bts_cell.verify_all_cells_are_onair(bts_id=self.bts_id, du_id=self.du_id)

    @log_as_robot_keyword
    @wait_until_check_succeeds(retry=300, retry_interval=30)
    def check_x2_link(self):
        """    Function if to check that X2 Link is in proper state
               Timeouted with decorator.
        :return: None.
        :raises AssertionError: If the X2 link status is not 'available'.
        """
        self.connect(increase_time_for_check=False, interface='mplane')
        lteenb_objects = self.bts_comm.admin.get_managed_objects(class_name='LTEENB_R',
                                                                 connection=self.bts_connection_name)
        assert len(lteenb_objects), 'Object LTEENB_R not ready on BTS'
        for lteenb in lteenb_objects:
            assert lteenb['parameters']['x2LinkStatus'] == 'available', ASSERT_MSG.format(
                message='x2LinkStatus is not available', expected='x2LinkStatus: available', current=lteenb)

    @log_as_robot_keyword
    def load_bsr_config(self, bsr_config_file, timeout=180):
        """    Function to load BSR (Beam Set Reference) configuration on BTS.
        :param str bsr_config_file: Path to BSR configuration file,
        :param int timeout: Maximum time in seconds to wait for BSR configuration upload,
        :return: None.
        :raises FileNotFoundError: If BSR configuration file does not exist.
        """
        log_info_to_console('Load BSR configuration.', log_hierarchy=2)
        log_info_to_console('Proper settings for BSR should be included in SCF.', log_hierarchy=3)
        if not os.path.exists(bsr_config_file):
            raise FileNotFoundError(f'BSR configuration file: {bsr_config_file} does not exist.')
        self.try_to_update_bts_software(timeout, bsr_config_file)

    @log_as_robot_keyword
    def install_certificates(self, certificates):
        """    Installs certificates on the BTS.
        :param list[dict] certificates: A list of dictionaries containing certificate parameters.
            Each dictionary should include:
            - 'cert_file' (str): Path to the certificate file.
            - 'cert_type' (str): Type of the certificate (e.g., 'CA', 'Server').
            - 'password' (str): Password for the certificate, if required.
            - 'key_pool_type' (str): Key pool type for the certificate.
        :return: None
        """
        connection = self.bts_connection_name
        for cert in certificates:
            log_info_to_console(f"Certificate {cert['cert_file'].split('/')[-1]} with following parameters {cert} "
                                f"will be uploaded to BTS", log_hierarchy=3)
            self.bts_comm.admin.install_certificate(cert_file=cert['cert_file'],
                                                    cert_type=cert['cert_type'],
                                                    cert_format=cert['cert_file'].split('.')[-1].upper(),
                                                    password=cert['password'],
                                                    key_pool_type=cert['key_pool_type'],
                                                    connection=connection)


